type meta struct {
	TokenUsage *types.TokenUsage `json:"token_usage"`
	Model      string            `json:"model"`
}

func sum(u *types.TokenUsage) int {
	if u == nil {
		return 0
	}
	return u.InputTokens + u.CacheCreationTokens + u.CacheReadTokens + u.OutputTokens
}

func main() {
	root := os.Args[1]
	verifyGemini(filepath.Join(root, "gemini"))
	verifyOpenCode(filepath.Join(root, "opencode"))
}

func files(dir string) []string {
	m, _ := filepath.Glob(filepath.Join(dir, "*.json"))
	var out []string
	for _, f := range m {
		if !strings.HasSuffix(f, ".meta.json") {
			out = append(out, f)
		}
	}
	sort.Strings(out)
	return out
}

func loadMeta(f string) meta {
	var m meta
	b, _ := os.ReadFile(strings.TrimSuffix(f, ".json") + ".meta.json")
	_ = json.Unmarshal(b, &m)
	return m
}

