// CheckpointRow is the per-(checkpoint, session) view a reader has after loading metadata.
type CheckpointRow struct {
	CheckpointID              string
	SessionID                 string
	Version                   int               // root token_usage_version; 0 for legacy
	CheckpointTranscriptStart int               // session metadata checkpoint_transcript_start; 0 when absent
	Usage                     *types.TokenUsage // session metadata token_usage (may be nil)
	CreatedAt                 time.Time
}

type Scope int
const (
	ScopeDelta           Scope = iota // token_usage covers only this checkpoint
	ScopeLegacyFromStart              // legacy row at transcript offset 0: may be the session's running total
)

func ClassifyScope(r CheckpointRow) Scope
// DedupeLegacyCheckpoints groups rows by SessionID, sorts each group by CreatedAt (stable),
// keeps the LATEST ScopeLegacyFromStart row plus every ScopeDelta row created after it,
// drops every row before that latest legacy-from-start row (they are contained in it),
// and returns the kept rows (in a deterministic order: by SessionID, then CreatedAt) plus
// the number collapsed. Version-2 rows (ScopeDelta) are never collapsed. A session with a
// single legacy-from-start row keeps it. Input is not mutated.
func DedupeLegacyCheckpoints(rows []CheckpointRow) (kept []CheckpointRow, collapsed int)
```
